with filtered_inventory as (select *, cast(quantity as double) quantity_num from inventory where product_id in (7, 8, 9, 10)), summary as (select case when quantity_num >= 68 then 'high' when quantity_num >= 30 then 'mid' else 'low' end quantity_num_bucket, count(distinct quantity) unique_products from filtered_inventory group by case when quantity_num >= 68 then 'high' when quantity_num >= 30 then 'mid' else 'low' end) select quantity_num_bucket, unique_products from summary order by unique_products desc, quantity_num_bucket
